      if(setup.step===1){
        if(setup.name.trim().length<2)return toast('Enter a display name.');
        if(!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(setup.email.trim()))return toast('Enter a valid email address.');
      }
